insert into mber_ntcn_iem_setup
select #{mberNtcnIemSetup.mberNo}
     , ntcn_setup_code
     , #{mberNtcnIemSetup.aplctnRecptnAt}
     , #{mberNtcnIemSetup.emailRecptnAt}
     , #{mberNtcnIemSetup.smsRecptnAt}
     , #{mberNtcnIemSetup.creatMberNo}
     , current_timestamp
     , #{mberNtcnIemSetup.changeMberNo}
     , current_timestamp
  from ntcn_setup_iem_role
 where role_id = #{roleId}
   and use_at = 'Y'

mapper.update:
update mber_ntcn_iem_setup
  set aplctn_recptn_at = coalesce(nullif(#{aplctnRecptnAt}, ''), aplctn_recptn_at)
    , email_recptn_at = coalesce(nullif(#{emailRecptnAt}, ''), email_recptn_at)
    , sms_recptn_at = coalesce(nullif(#{smsRecptnAt}, ''), sms_recptn_at)
    , change_mber_no = #{changeMberNo}
    , change_dt = current_timestamp
where mber_no = #{mberNo}
  and ntcn_setup_code = #{ntcnSetupCode}
